}

// has_owner_with keeps the rows that have a `owner` that `configure` keeps.
pub fn (q GadgetQuery) has_owner_with(configure fn (UserQuery) UserQuery) GadgetQuery {
	return q.where(gadget_has_owner_with(...configure(q.graph.users()).query.conds))
