// query_owner starts a query of the `owner` of the rows that match this
// query's conditions; its order, limit and offset don't apply.
pub fn (q GadgetQuery) query_owner() UserQuery {
	return q.graph.users().where(load.in_sub('id', load.Sub{ table: 'gadgets', column: 'owner_id', kind: .int, conds: q.query.conds }))
}

// query_likers starts a query of the `likers` of the rows that match this
// query's conditions; its order, limit and offset don't apply.
pub fn (q GadgetQuery) query_likers() UserQuery {
	return q.graph.users().where(load.in_sub('id', load.Sub{ table: 'likes', column: 'user_id', kind: .int, conds: [load.in_sub('gadget_id', load.Sub{ table: 'gadgets', column: 'id', kind: .i64, conds: q.query.conds })] }))
}

// only returns the one matching row, with the requested edges: a
// `NotFoundError` when there is none, a `NotSingularError` when there are more.
pub fn (q GadgetQuery) only() !GadgetNode {
	nodes := q.limit(2).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'gadgets'
		}
	}
	if nodes.len > 1 {
		return NotSingularError{
			table: 'gadgets'
		}
	}
	return nodes[0]
}

// ids returns the keys of the matching rows, in order, and no edges.
pub fn (q GadgetQuery) ids() ![]i64 {
	keys := load.select_keys_where(q.graph.client.conn, 'gadgets', 'id', .i64, q.graph.client.prepare_query('gadgets', q.query)!, true)!
	return keys.map(it.i64())
}

// first_id returns the key of the first matching row, or a `NotFoundError`.
pub fn (q GadgetQuery) first_id() !i64 {
	ids := q.limit(1).ids()!
	if ids.len == 0 {
		return NotFoundError{
			table: 'gadgets'
		}
	}
	return ids[0]
}

// only_id returns the key of the one matching row: a `NotFoundError` when
// there is none, a `NotSingularError` when there are more.
pub fn (q GadgetQuery) only_id() !i64 {
	ids := q.limit(2).ids()!
	if ids.len == 0 {
		return NotFoundError{
			table: 'gadgets'
		}
	}
	if ids.len > 1 {
		return NotSingularError{
			table: 'gadgets'
		}
	}
	return ids[0]
}

// exist reports whether any row matches.
pub fn (q GadgetQuery) exist() !bool {
	return q.limit(1).ids()!.len > 0
}

// select reads only `columns`, and the key, of the rows; the others keep their
// zero values. An edge load needs the columns it follows.
pub fn (q GadgetQuery) select(columns ...string) GadgetQuery {
	mut all := columns.clone()
	if 'id' !in all {
		all << 'id'
	}
	mut next := q
	next.query = load.Query{
		...q.query
		columns: all
	}
	return next
}

// unique makes `scan` read each distinct row once.
pub fn (q GadgetQuery) unique() GadgetQuery {
	mut next := q
	next.query = load.Query{
		...q.query
		distinct: true
	}
	return next
}

// scan reads the matching rows into `T`, the app's struct for some of the
// columns, by column name.
pub fn (q GadgetQuery) scan[T]() ![]T {
	return load.select_into[T](q.graph.client.conn, 'gadgets', 'id', .i64, q.graph.client.prepare_query('gadgets', q.query)!)
}

// order_by orders the rows by `orders` too, after the orders given before,
// such as `vgraph.desc('id').nulls_last()`.
pub fn (q GadgetQuery) order_by(orders ...load.Order) GadgetQuery {
	mut all := q.query.orders.clone()
	all << orders
	mut next := q
	next.query = load.Query{
		...q.query
		orders: all
	}
	return next
}

// for_update locks the matching rows (FOR UPDATE) until the transaction ends.
// It runs in `tx`, on PostgreSQL.
pub fn (q GadgetQuery) for_update() GadgetQuery {
	mut next := q
	next.query = load.Query{
		...q.query
		lock: load.Lock{
			...q.query.lock
			mode: .update
		}
	}
	return next
}

// for_share locks the matching rows (FOR SHARE) until the transaction ends.
// It runs in `tx`, on PostgreSQL.
pub fn (q GadgetQuery) for_share() GadgetQuery {
	mut next := q
	next.query = load.Query{
		...q.query
		lock: load.Lock{
			...q.query.lock
			mode: .share
		}
	}
	return next
}

// no_wait makes the lock one that fails at once on a row another transaction locked.
pub fn (q GadgetQuery) no_wait() GadgetQuery {
	mut next := q
	next.query = load.Query{
		...q.query
		lock: load.Lock{
			...q.query.lock
			no_wait: true
		}
	}
	return next
}

// skip_locked makes the lock one that leaves out the rows other transactions locked.
pub fn (q GadgetQuery) skip_locked() GadgetQuery {
	mut next := q
	next.query = load.Query{
		...q.query
		lock: load.Lock{
			...q.query.lock
			skip_locked: true
		}
	}
	return next
}

