// GadgetGroupBy groups the rows of a `GadgetQuery`. Start one with `group_by`.
pub struct GadgetGroupBy {
	query GadgetQuery
pub:
	columns    []string
	aggregates []load.Aggregate
}

// group_by groups the matching rows by `columns`. It needs a vgraph driver.
pub fn (q GadgetQuery) group_by(columns ...string) GadgetGroupBy {
	return GadgetGroupBy{
		query:   q
		columns: columns
	}
}

// aggregate adds what each group gets, such as `vgraph.count()` or
// `vgraph.sum('views')`.
pub fn (g GadgetGroupBy) aggregate(aggregates ...load.Aggregate) GadgetGroupBy {
	mut all := g.aggregates.clone()
	all << aggregates
	return GadgetGroupBy{
		...g
		aggregates: all
	}
}

// all returns the groups, ordered by their columns.
pub fn (g GadgetGroupBy) all() ![]load.Group {
	q := g.query
	return load.group_where(q.graph.client.conn, 'gadgets', q.graph.client.prepare_query('gadgets', q.query)!, g.columns.map(load.GroupColumn{
		name: it
		typ:  gadget_column_type(it)
	}), g.aggregates)
}

// scan reads the groups into `T`, by name: its fields named after the grouped
// columns and the aggregates (`count`, `sum_views`).
pub fn (g GadgetGroupBy) scan[T]() ![]T {
	return load.scan_groups[T](g.all()!)
}

// gadget_column_type returns the V type of a column of `gadgets`.
fn gadget_column_type(column string) string {
	return match column {
		'Stamps.created_at' { 'time.Time' }
		'Stamps.updated_at' { 'time.Time' }
		'id' { 'i64' }
		'owner_id' { 'int' }
		'serial_no' { 'string' }
		'color' { 'enum' }
		'level' { 'i8' }
		'weight' { 'u16' }
		'parts' { 'u32' }
		'big' { 'u64' }
		'ratio' { 'f32' }
		'rating' { '?f64' }
		'score' { '?i64' }
		'active' { '?bool' }
		'tags' { 'string' }
		else { '' }
	}
}

// order_by_owner_name orders the rows by the `name` of their `owner`.
pub fn (q GadgetQuery) order_by_owner_name() GadgetQuery {
	return q.order_by(load.Order{
		expr: '(SELECT "t1"."name" FROM "users" AS "t1" WHERE "t1"."id" = "t0"."owner_id")'
	})
}

// order_by_owner_name_desc orders the rows by the `name` of their
// `owner`, descending.
pub fn (q GadgetQuery) order_by_owner_name_desc() GadgetQuery {
	return q.order_by(load.Order{
		expr: '(SELECT "t1"."name" FROM "users" AS "t1" WHERE "t1"."id" = "t0"."owner_id")'
		desc: true
	})
}

// order_by_owner_spouse_id orders the rows by the `spouse_id` of their `owner`.
