// with_named_likers loads `likers` as `configure` says into
// `named_likers[name]`, besides any other load of it.
pub fn (q GadgetQuery) with_named_likers(name string, configure ...fn (UserQuery) UserQuery) GadgetQuery {
	mut next := q
	mut named := q.named_likers.clone()
	named[name] = configure
	next.named_likers = named
	return next
}

// with_owner loads each row's `owner` (many_to_one `users`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q GadgetQuery) with_owner(configure ...fn (UserQuery) UserQuery) GadgetQuery {
	mut next := q
	next.with_owner = true
	next.owner_fns = configure
	return next
}

// with_likers loads each row's `likers` (many_to_many `users`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q GadgetQuery) with_likers(configure ...fn (UserQuery) UserQuery) GadgetQuery {
	mut next := q
	next.with_likers = true
	next.likers_fns = configure
	return next
}

// all returns the matching rows, with the requested edges.
pub fn (q GadgetQuery) all() ![]GadgetNode {
	rows := load.select_where[models.Gadget](q.graph.client.conn, q.graph.client.prepare_query('gadgets', q.query)!)!
	return q.nodes(rows)
}

// first returns the first matching row, with the requested edges, or a
// `NotFoundError`.
pub fn (q GadgetQuery) first() !GadgetNode {
	nodes := q.limit(1).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'gadgets'
		}
	}
	return nodes[0]
}

// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q GadgetQuery) nodes(rows []models.Gadget) ![]GadgetNode {
	mut nodes := rows.map(GadgetNode{
		graph:  q.graph
		gadget: it
	})
	if q.with_owner {
		found := q.load_owner(rows, q.owner_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.gadget.id.str()] or { [] }
			if list.len > 0 {
				node.owner = &UserNode{
					...list[0]
				}
			}
			node.loaded << 'owner'
		}
	}
	if q.with_likers {
		found := q.load_likers(rows, q.likers_fns)!
		for mut node in nodes {
			node.likers = found[node.gadget.id.str()] or { [] }
			node.loaded << 'likers'
		}
	}
	for name, fns in q.named_likers {
		found := q.load_likers(rows, fns)!
		for mut node in nodes {
			node.named_likers[name] = found[node.gadget.id.str()] or { [] }
		}
	}
	return nodes
}

// load_owner loads the `owner` of `rows`, keyed by each row's key.
fn (q GadgetQuery) load_owner(rows []models.Gadget, fns []fn (UserQuery) UserQuery) !map[string][]UserNode {
	mut sub := q.graph.users()
	for configure in fns {
		sub = configure(sub)
	}
	mut keys := []string{}
	for row in rows {
		keys << row.owner_id.str()
	}
	targets := sub.nodes(load.select_in[models.User](q.graph.client.conn, 'id', load.unique(keys),
		query: q.graph.client.prepare_query('users', sub.query)!
	)!)!
	mut by_key := map[string]UserNode{}
	for target in targets {
		by_key[target.user.id.str()] = target
	}
	mut found := map[string][]UserNode{}
	for row in rows {
		if target := by_key[row.owner_id.str()] {
			found[row.id.str()] = [target]
		}
	}
	return found
}

// owner_or_err returns the `owner`: a `NotLoadedError` when the query didn't
// load it, a `NotFoundError` when the row has none.
pub fn (n GadgetNode) owner_or_err() !&UserNode {
	if 'owner' !in n.loaded {
		return NotLoadedError{
			edge: 'gadgets.owner'
		}
	}
	if target := n.owner {
		return target
	}
	return NotFoundError{
		table: 'users'
	}
}

// load_likers loads the `likers` of `rows`, keyed by each row's key.
fn (q GadgetQuery) load_likers(rows []models.Gadget, fns []fn (UserQuery) UserQuery) !map[string][]UserNode {
	mut sub := q.graph.users()
	for configure in fns {
		sub = configure(sub)
	}
	if sub.query.limit > 0 || sub.query.offset > 0 {
		prepared := q.graph.client.prepare_query('users', sub.query)!
		cut := load.link_each(q.graph.client.conn, 'likes', 'gadget_id', 'user_id',
			rows.map(it.id.str()), .i64, .int, 'users', 'id', load.Query{
				...prepared
				conds: prepared.conds
			})!
		// the targets by key: the join rows give their order
		found := sub.nodes(load.select_in[models.User](q.graph.client.conn, 'id',
			load.unique(cut.map(it[1])),
			query: load.Query{ ...prepared, order: '', desc: false, orders: []load.Order{}, limit: 0, offset: 0 }
		)!)!
		mut by_key := map[string]UserNode{}
		for target in found {
			by_key[target.user.id.str()] = target
		}
		mut cut_linked := map[string][]UserNode{}
		for pair in cut {
			if target := by_key[pair[1]] {
				cut_linked[pair[0]] << target
			}
		}
		return cut_linked
	}
	pairs := load.link_pairs(q.graph.client.conn, 'likes', 'gadget_id',
		'user_id', rows.map(it.id.str()), .i64, .int)!
	targets := sub.nodes(load.select_in[models.User](q.graph.client.conn, 'id',
		load.unique(pairs.map(it[1])),
		query: q.graph.client.prepare_query('users', sub.query)!
	)!)!
	// each parent's targets in the order of the query
	mut parents_of := map[string][]string{}
	for pair in pairs {
		parents_of[pair[1]] << pair[0]
	}
	mut linked := map[string][]UserNode{}
	for target in targets {
		for parent in parents_of[target.user.id.str()] or { [] } {
			linked[parent] << target
		}
	}
	return linked
}

// likers_or_err returns the `likers`, or a `NotLoadedError` when the query
// didn't load them.
pub fn (n GadgetNode) likers_or_err() ![]UserNode {
	if 'likers' !in n.loaded {
		return NotLoadedError{
			edge: 'gadgets.likers'
		}
	}
	return n.likers
}

// tags_value returns `tags`, decoded from JSON.
pub fn (n GadgetNode) tags_value() ![]string {
	text := n.gadget.tags
	return json2.decode[[]string](text)!
}

// query_owner starts a query of this row's `owner`, which matches
// nothing when the row has none.
pub fn (n GadgetNode) query_owner() UserQuery {
	key := n.gadget.owner_id
	return n.graph.users().where(load.eq('id', key))
}

// query_likers starts a query of this row's `likers`. It reads the join
// table `likes` first, so it can fail.
pub fn (n GadgetNode) query_likers() !UserQuery {
	pairs := load.link_pairs(n.graph.client.conn, 'likes', 'gadget_id',
		'user_id', [n.gadget.id.str()], .i64, .int)!
	return n.graph.users().where(load.in_keys('id', pairs.map(it[1]), .int))
}
